INSERT INTO rule_field (field, sql_name, type, field_group, is_loaded, in_layout, read_by_rules, description) VALUES
  ('mask_id', 'member_id', 'text', 'Identity', 1, '341,377', NULL, 'Masked member identifier (m1, m2, ...); one row per member. Replaces member_id and life_id in this file.'),
  ('rank_PURECS_per_payable', 'rank_purecs_per_payable', 'num', 'Risk score (extract-computed)', 0, '341', NULL, 'Rank of the member within the PURECS allocation by diabetes / hypertension related payable in the last 12 months (l12m_payable_DiaborHTNrelated), 1 = highest'),
  ('GENDER', 'gender', 'text', 'Who they are', 1, '341,377', 'rule_builder_field_group:Who they are; rule_risk_band:A', 'Gender, taken from the member''s most recent claim.'),
  ('AGE', 'age', 'num', 'Who they are', 1, '341,377', 'rule_builder_field_group:Who they are; rule_risk_band:A', 'Age in years, from the latest year in the age table.'),
  ('NATIONALITY', 'nationality', 'text', 'Who they are', 1, '341,377', 'rule_builder_field_group:Who they are; rule_guardrail:G10', 'Member''s nationality, provided by DABI team'),
  ('plan_name', 'plan_name', 'text', 'Who they are', 1, '341', NULL, 'Insurance plan, taken from the member''s most recent claim.'),
  ('policy_group', 'policy_group', 'text', 'Who they are', 1, '341,377', 'rule_builder_field_group:Who they are', 'Employer or policy group behind the member''s policy (Final_Policy_Group), looked up by member_id from the premium and policy data shared by the DABI team; ''-'' if the member is not in that data.'),
  ('policy_type', 'policy_type', 'text', 'Who they are', 1, '341,377', 'rule_builder_field_group:Who they are', 'Type of policy, for example Group vs. Individual (Final_Policy_Type), from the premium and policy data shared by the DABI team; ''-'' if not found.'),
  ('cohort_t2d_l12m', 'cohort_t2d_l12m', 'flag', 'Pathway', 1, '341,377', 'rule_builder_field_group:Health; rule_trigger:pathway', '1 if the member had a claim billed for type 2 diabetes (E11) as a chronic condition in the last 12 months (Nov 2025 to Oct 2026).'),
  ('cohort_htn_l12m', 'cohort_htn_l12m', 'flag', 'Pathway', 1, '341,377', 'rule_builder_field_group:Health; rule_risk_band:C; rule_trigger:pathway', '1 if the member had a claim billed for hypertension (I10) as a chronic condition in the last 12 months (Nov 2025 to Oct 2026).'),
  ('t2d_identified_by', 't2d_identified_by', 'text', 'Pathway', 1, '341,377', 'rule_trigger:pathway', 'How diabetes shows in the historical claims data: DX + RX (diagnosed and filling diabetes medicines), DX only (diagnosed, no diabetes medicine filled through Daman), RX only (filling diabetes medicines but never billed with E11), Not T2D.'),
  ('htn_identified_by', 'htn_identified_by', 'text', 'Pathway', 1, '341,377', 'rule_risk_band:C; rule_trigger:pathway', 'The same for hypertension (I10 diagnosis and blood-pressure medicines): DX + RX, DX only, RX only, Not HTN.'),
  ('t2d_category', 't2d_category', 'text', 'Pathway', 1, '341,377', 'rule_trigger:pathway', 'Network attachment, first that applies: In PHG network for the specified condition in 2026 (a 2026 diabetes claim at SEHA or SSMC); In PHG network for other chronic conditions in 2026; In PHG for chronic conditions prior to 2026; In PHG for non-chronic conditions (only acute care at PHG since 2024); Not in PHG network.'),
  ('htn_category', 'htn_category', 'text', 'Pathway', 1, '341,377', 'rule_trigger:pathway', 'Network attachment, first that applies: In PHG network for the specified condition in 2026 (a 2026 hypertension claim at SEHA or SSMC); In PHG network for other chronic conditions in 2026; In PHG for chronic conditions prior to 2026; In PHG for non-chronic conditions (only acute care at PHG since 2024); Not in PHG network.'),
  ('GWP', 'gwp', 'num', 'Who they are', 1, '341,377', 'rule_builder_field_group:Who they are', 'Gross written premium for the member, AED, from the premium data shared by the DABI team; ''-'' if not found.'),
  ('Risk Premium', 'risk_premium', 'num', 'Who they are', 1, '341,377', 'rule_builder_field_group:Who they are', 'Risk premium for the member, AED, from the premium data shared by the DABI team; ''-'' if not found.'),
  ('Exclusion', 'excluded', 'flag', 'Exclusions and gates', 1, '341,377', 'rule_builder_field_group:Other; rule_guardrail:G1c', '1 = left out of outreach. Any of: cancer claim in the last 24 months (flag_oncology_l24m); outside the PHG network with 75%+ of outpatient encounters at one provider and more than one outpatient encounter (loyal out-of-network member); palliative / hospice / long-term care; dialysis or an AV-access procedure in the last 12 months; transplant; advanced neurological or major congenital condition; psychiatric inpatient stay, active substance use or advanced dementia; ventilator / TPN / 24-hour home nursing; pregnant or post-partum; more than 60% of cost since 2024 in one episode; specialty medicines more than 60% of cost since 2024. Each part is its own column further right.'),
  ('P1_Complication', 'p1_complication', 'flag', 'Persona and targeting', 1, '341,377', 'rule_loop_step:Cohort', '1 if any of these was billed on any claim since January 2024: kidney disease of any kind, dialysis, stroke, heart failure, heart attack, or a diabetic kidney, eye, foot or circulation complication (flag_any_kidney_disease, flag_dialysis, flag_stroke, flag_heart_failure, flag_mi, flag_dm_kidney, flag_dm_eye, flag_dm_foot, flag_dm_circulatory).'),
  ('P2_Recurrent_ED_IP', 'p2_recurrent_ed_ip', 'flag', 'Persona and targeting', 1, '341,377', 'rule_loop_step:Cohort', '1 if emergency visits plus hospital admissions in the last 12 months (ed_visits_l12m + ip_admissions_l12m) total 2 or more.'),
  ('P3_slipping', 'p3_slipping', 'flag', 'Persona and targeting', 1, '341,377', 'rule_loop_step:Cohort', '1 if a diabetes or BP medicine ran out more than 30 days ago, or adherence (PDC) is below 0.8 for non-insulin diabetes medicines or for BP medicines.'),
  ('P5_newlydiagnosed', 'p5_newlydiagnosed', 'flag', 'Persona and targeting', 1, '341,377', 'rule_loop_step:Cohort', '1 if the first diabetes (E11) or hypertension (I10) claim was in the 180 days before the review date (31 Oct 2026).'),
  ('P3_offradar', 'p3_offradar', 'flag', 'Persona and targeting', 1, '341,377', 'rule_loop_step:Cohort', '1 if no GP and no specialist consultation in the last 6 months, or the member has diabetes and no HbA1c test billed in the 365 days before the review date.'),
  ('P4_uncontrolled', 'p4_uncontrolled', 'flag', 'Persona and targeting', 1, '341,377', 'rule_loop_step:Cohort', '1 if the latest HbA1c is above 7% (values between 3 and 20 only), or the latest systolic blood pressure is above 130 mmHg (values between 60 and 260 only).'),
  ('Persona', 'persona', 'text', 'Persona and targeting', 1, '341,377', 'rule_loop_step:Cohort', 'One persona per member, the first that applies: 1. Complications (P1), 2. Recurrent ED/IP (P2), 3. Drifting from care (P3_slipping or P3_offradar), 4. Uncontrolled (P4), 5. Newly Diagnosed (P5), 6. Others / Stable.'),
  ('Trig1_HbA1c_above_target', 'trig1_hba1c_above_target', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig1', '1 if the member has diabetes and the latest HbA1c is 6.5% or more (values between 3 and 20 only).'),
  ('Trig2a_NoACEiARB_KidneyOrCAD', 'trig2a_noaceiarb_kidneyorcad', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig2', '1 if the member has diabetes and hypertension, is on neither an ACE inhibitor nor an ARB, and has diabetic kidney disease, CKD, heart attack, ischaemic heart disease or stroke (on any claim since January 2024).'),
  ('Trig2b_ACEi_plus_ARB', 'trig2b_acei_plus_arb', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig2', '1 if an ACE inhibitor and an ARB are both active and their supplies overlapped by more than 30 days (a combination DoH says not to use).'),
  ('Trig2_HTN_tx_review', 'trig2_htn_tx_review', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig2', '1 if Trig2a or Trig2b is 1.'),
  ('Trig3a_hypoglycemia_rev', 'trig3a_hypoglycemia_rev', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig3', '1 if there was a hypoglycaemia claim (E11.64x or E16.0-E16.2) in the last 90 days.'),
  ('Trig3b_glucagon_not_dispensed', 'trig3b_glucagon_not_dispensed', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig3', '1 if the member has diabetes, had no rescue glucagon in the last 12 months, and is on insulin, or on a sulfonylurea with a hypoglycaemia claim on any claim since January 2024.'),
  ('Trig3_hypoglycemia_tx', 'trig3_hypoglycemia_tx', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig3', '1 if Trig3a or Trig3b is 1.'),
  ('Trig4a_NoFollowup_post_discharge', 'trig4a_nofollowup_post_discharge', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig4', '1 if discharged from hospital and no clinic visit since (same as flag_no_visit_after_discharge).'),
  ('Trig4b_postdischarge_medsgap', 'trig4b_postdischarge_medsgap', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig4', '1 if a diabetes or BP medicine filled before the last admission was not refilled within 30 days of discharge.'),
  ('Trig4_post_discharge_care', 'trig4_post_discharge_care', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_alert:AMBER; rule_contact_priority:P1–P4; rule_trigger:Trig4', '1 if Trig4a or Trig4b is 1.'),
  ('Trig5a_Kidney_screen_due', 'trig5a_kidney_screen_due', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig5', '1 if the member has diabetes and the urine albumin test or the eGFR result is missing or older than 365 days.'),
  ('Trig5b_CKD_monitoring', 'trig5b_ckd_monitoring', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig5', '1 if the member has CKD or diabetic kidney disease and the eGFR result or the urine albumin test is missing or older than 90 days.'),
  ('Trig5c_Neph_due', 'trig5c_neph_due', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig5', '1 if the latest eGFR is below 30, the member is not on dialysis, and there was no nephrology visit in the last 365 days.'),
  ('Trig5_Kidney_check', 'trig5_kidney_check', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_alert:YELLOW; rule_trigger:Trig5', '1 if Trig5a, Trig5b or Trig5c is 1.'),
  ('Trig6_HbA1c_due', 'trig6_hba1c_due', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_alert:YELLOW; rule_trigger:Trig6', '1 if the member has diabetes and any of: no HbA1c test in 180 days; latest HbA1c 7% or more and no test in 90 days; a hypo- or hyperglycaemia claim in the last 6 months and no test in 90 days; a new diabetes medicine class started in the last 90 days and no test since.'),
  ('Trig7_Renal_Potassium_due', 'trig7_renal_potassium_due', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_alert:YELLOW; rule_trigger:Trig7', '1 if the member has hypertension and either the newest ACE inhibitor, ARB, MRA or thiazide class started 14+ days ago with no potassium test since, or one of these is active with no potassium test in 365 days.'),
  ('Trig8_nutrition_due', 'trig8_nutrition_due', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig8', '1 if the member has diabetes and had no diabetes-educator visit and no dietitian visit in the last 365 days.'),
  ('Trig9_medication_adherence', 'trig9_medication_adherence', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig9', '1 if a diabetes or BP medicine ran out more than 30 days ago, or PDC is below 0.8 for non-insulin diabetes or BP medicines.'),
  ('Trig10_new_diagnosis', 'trig10_new_diagnosis', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_trigger:Trig10', '1 if the first diabetes or hypertension claim was in the last 180 days, or a member without diabetes has fasting glucose 7.0+ mmol/L, 2-hour glucose 11.1+, random glucose 11.1+ or HbA1c 6.5%+.'),
  ('Trig11_annual_labs_due', 'trig11_annual_labs_due', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_alert:YELLOW; rule_trigger:Trig11', '1 if on an ACE inhibitor or ARB with no potassium test in 365 days, or the member has diabetes and any of these is missing or older than 365 days: lipid panel, urine albumin, liver function, eGFR result, CBC, vitamin B12 (B12 only if metformin is active).'),
  ('Trig12_eyeexam_due', 'trig12_eyeexam_due', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_alert:YELLOW; rule_trigger:Trig12', '1 if the member has diabetes and had no retinal screening and no eye-doctor visit for 365 days when there is diabetic eye disease or HbA1c 7%+, otherwise for 730 days.'),
  ('Trig13_highriskfoot_monitor', 'trig13_highriskfoot_monitor', 'flag', 'Trigger flags (extract-computed)', 1, '341,377', 'rule_alert:YELLOW; rule_trigger:Trig13', '1 if dialysis, diabetic foot, amputation or diabetic neuropathy (any claim since January 2024), and no podiatry visit in the last 180 days.'),
  ('# of triggers', 'n_triggers', 'num', 'Risk score (extract-computed)', 1, '341,377', 'rule_trigger:all', 'Number of main triggers that are 1: Trig1 to Trig13 (the a / b / c sub-triggers are not counted separately). 0-13.'),
  ('HbA1c_score', 'hba1c_score', 'num', 'Risk score (extract-computed)', 1, '341,377', 'rule_risk_band:C', 'HbA1c points (H), from the latest HbA1c: 0 if below 7%, 1 if 7.0-7.9%, 2 if 8.0-8.9%, 3 if 9.0-9.9%, 4 if 10% or more; 0 when there is no result.'),
  ('Clinical_score', 'clinical_score', 'num', 'Risk score (extract-computed)', 1, '341,377', 'rule_risk_band:C', 'Clinical score C, maximum 5: HbA1c_score + 2 if hypertension (cohort_htn_l12m = 1) + 3 if DKA coded in the last 12 months (flag_dka_l12m) + 2 if hypoglycaemia coded in the last 12 months (flag_dm_hypoglycaemia_l12m), capped at 5.'),
  ('Comorbid_complication_score', 'comorbid_complication_score', 'num', 'Risk score (extract-computed)', 1, '341,377', 'rule_risk_band:M', 'Comorbidity and complication score M, maximum 6, from conditions billed on any claim since January 2024: dyslipidaemia 1 (first_dyslipidemia_date present), current smoker 1 (flag_current_smoker_l12m), obesity 1 (flag_obesity), stroke 3 (flag_stroke), heart failure 3 (flag_heart_failure), CAD / heart attack 3 (flag_mi or flag_ischemic_heart_disease), diabetic eye disease 2 (flag_dm_eye), diabetic neuropathy 1 (flag_dm_neuropathy), diabetic foot 4 (flag_dm_foot), amputation 4 (flag_amputation), diabetic circulation / PAD 3 (flag_dm_circulatory); total capped at 6.'),
  ('eGFR + UACR points', 'egfr_uacr_points', 'num', 'Risk score (extract-computed)', 1, '341,377', 'rule_risk_band:K', 'Kidney points from lab results, maximum 5. eGFR (when there is a result): 4 if on dialysis (flag_dialysis), otherwise 0 if 60+, 1 if 45-59, 2 if 30-44, 3 if 15-29, 4 if below 15. Plus UACR (when there is a result): 0 if below 30 mg/g, 1 if 30-299, 2 if 300+.'),
  ('Kidney_score', 'kidney_score', 'num', 'Risk score (extract-computed)', 1, '341,377', 'rule_risk_band:K', 'Kidney score K, maximum 5: the lab-based points (eGFR + UACR points). When both eGFR and UACR are missing, the documented CKD stage is used instead (ckd_stage_l12m): Not documented / Stage 1-2 = 0, Stage 3a = 1, Stage 3b = 2, Stage 4 = 3, Stage 5 / kidney failure = 4.'),
  ('Utilization_score', 'utilization_score', 'num', 'Risk score (extract-computed)', 1, '341,377', 'rule_risk_band:U', 'Utilisation score U, maximum 5: diabetes / hypertension related ED visits in the last 12 months (l12m_ED_visits_DiaborHTNrelated) = 1 point each up to 3, plus related admissions (l12m_IP_admissions_DiaborHTNrelated): 1 admission = 3, 2 or more = 4; capped at 5.'),
  ('Age_sex_score', 'age_sex_score', 'num', 'Risk score (extract-computed)', 1, '341,377', 'rule_risk_band:A', 'Age and sex score A, 0-2. Men: under 40 = 0, 40-59 = 1, 60+ = 2. Women: under 45 = 0, 45-69 = 1, 70+ = 2.'),
  ('Total_risk_Score', 'total_risk_score', 'num', 'Risk score (extract-computed)', 1, '341,377', 'rule_queue_order:1–4; rule_tier:R', 'Total risk score R = Clinical + Comorbidity + Kidney + Utilisation + Age/sex (0-23).'),
  ('Risk_tier', 'risk_tier', 'text', 'Risk score (extract-computed)', 1, '341,377', 'rule_tier:tier', 'Tier from the total risk score: 0-3 = 4. Low, 4-7 = 3. Moderate, 8-12 = 2. High, 13+ = 1. Very High.'),
  ('Cohort_allocation', 'cohort_allocation', 'text', 'Persona and targeting', 1, '341,377', 'rule_loop_step:Cohort', 'Programme the member is allocated to by tier: Very High or High = ''PREVHEATH''; Moderate or Low = ''PURECS''.'),
  ('Priority_clinical_review', 'priority_clinical_review', 'flag', 'Risk score (extract-computed)', 1, '341,377', 'rule_alert:RED; rule_queue_order:1–4; rule_safety_flag:safety', 'Safety flag, independent of the tier: 1 if DKA (flag_dka_l12m) or a hypoglycaemia was coded in the last 12 months.'),
  ('Last_HbA1c_Value', 'last_hba1c_value', 'num', 'Labs and readings', 1, '341,377', 'rule_alert:AMBER; rule_builder_field_group:Tests & results; rule_risk_band:C; rule_trigger:Trig1; rule_trigger:Trig6', 'Latest HbA1c (3-month average blood sugar), in %. Readings above 20 are treated as mmol/mol and converted to %.'),
