  ('excl_palliative_hospice_ltc_reason', 'excl_palliative_hospice_ltc_reason', 'text', 'Exclusions and gates', 0, '341,377', NULL, 'Which part applied: ''Palliative / hospice'', ''Long-term care facility'', or both.'),
