  ('excl_transplant_reason', 'excl_transplant_reason', 'text', 'Exclusions and gates', 0, '341,377', NULL, 'Which part applied: ''Transplant'', ''Anti-rejection therapy'', ''Transplant waiting list''.'),
  ('flag_excl_adv_neuro_congenital_l12m', 'flag_excl_adv_neuro_congenital_l12m', 'flag', 'Exclusions and gates', 1, '341,377', 'rule_guardrail:G1c', '1 if any of these in the last 12 months (Nov 2025 to Oct 2026): advanced Parkinson''s (motor fluctuations, inpatient stay, deep brain stimulation or infusion therapy), ALS / motor neuron disease, late-stage MS (MS with an inpatient stay or a wheelchair / bed-bound / dependency code), a major congenital condition, or a severe brain / spinal injury with attendant care (or paraplegia / tetraplegia / vegetative state).'),
  ('excl_adv_neuro_congenital_reason', 'excl_adv_neuro_congenital_reason', 'text', 'Exclusions and gates', 0, '341,377', NULL, 'Which conditions applied, for example ''ALS / MND, Late-stage MS''.'),
  ('flag_excl_psych_sud_dementia_l12m', 'flag_excl_psych_sud_dementia_l12m', 'flag', 'Exclusions and gates', 1, '341,377', 'rule_guardrail:G1c', '1 if any of these in the last 12 months (Nov 2025 to Oct 2026): a psychiatric inpatient stay, an active substance use disorder (F10-F19 except nicotine and ''in remission'', or an addiction-treatment medicine), or advanced dementia (severe dementia code, or dementia with a mobility-dependence code).'),
  ('excl_psych_sud_dementia_reason', 'excl_psych_sud_dementia_reason', 'text', 'Exclusions and gates', 0, '341,377', NULL, 'Which conditions applied: ''Psychiatric inpatient stay'', ''Active substance use disorder'', ''Advanced dementia''.'),
