  ('excl_ventilator_tpn_homenursing_reason', 'excl_ventilator_tpn_homenursing_reason', 'text', 'Exclusions and gates', 0, '341,377', NULL, 'Which part applied, for example ''TPN, Home nursing (120 days)''.'),
  ('home_nursing_days_l12m', 'home_nursing_days_l12m', 'num', 'Exclusions and gates', 1, '341,377', 'rule_guardrail:G1c', 'Number of different days with home nursing billed in the last 12 months.'),
