  ('max_episode_share_since2024', 'max_episode_share_since2024', 'share', 'Exclusions and gates', 0, '341,377', NULL, 'Share of everything Daman paid for the member since January 2024 that comes from their single most expensive episode of care (0-1). Above 0.60 sets flag_excl_single_episode_gt60pct.'),
