  ('flag_current_smoker_l12m', 'flag_current_smoker_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M', '1 if current tobacco use was recorded in the last 12 months (Nov 2025 to Oct 2026): nicotine dependence (F17.2x, except ''in remission''), tobacco use (Z72.0), smoking in pregnancy (O99.33x), tobacco counselling (Z71.6, CPT 99406 / 99407), CPT II current-smoker codes (1034F, 1035F, 4000F, 4001F), a stop-smoking medicine (varenicline / Champix, Zyban, nicotine replacement), or a smoking observation (codes 3450 / 3451).'),
  ('last_smoking_evidence_date', 'last_smoking_evidence_date', 'date', 'Labs and readings', 1, '341,377', 'rule_risk_band:M', 'Latest date with any of the evidence above, from claims or observations, since January 2024.'),
  ('flag_former_smoker_code', 'flag_former_smoker_code', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M', '1 if a former-smoker code was billed on any claim since January 2024: history of nicotine dependence (Z87.891) or nicotine dependence ''in remission'' (F17.201, F17.211, F17.221, F17.291).'),
  ('flag_ckd_l12m', 'flag_ckd_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:K; rule_trigger:Trig2; rule_trigger:Trig5', '1 if chronic kidney disease (N18, any stage) was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_ckd, which looks back to January 2024.'),
  ('flag_hypertensive_kidney_disease_l12m', 'flag_hypertensive_kidney_disease_l12m', 'flag', 'Conditions and complications', 0, '341,377', NULL, '1 if kidney disease caused by high blood pressure was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_hypertensive_kidney_disease, which looks back to January 2024.'),
  ('flag_kidney_failure_l12m', 'flag_kidney_failure_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:K', '1 if end-stage kidney disease or dependence on dialysis was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_kidney_failure, which looks back to January 2024.'),
  ('flag_acute_kidney_injury_l12m', 'flag_acute_kidney_injury_l12m', 'flag', 'Conditions and complications', 0, '341,377', NULL, '1 if acute kidney injury was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_acute_kidney_injury, which looks back to January 2024.'),
  ('flag_any_kidney_disease_l12m', 'flag_any_kidney_disease_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:K', '1 if any chronic, hypertensive or diabetic kidney disease, or kidney failure was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_any_kidney_disease, which looks back to January 2024.'),
