  ('flag_mi_l12m', 'flag_mi_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M', '1 if a heart attack, recent or past was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_mi, which looks back to January 2024.'),
  ('flag_other_cvd_l12m', 'flag_other_cvd_l12m', 'flag', 'Conditions and complications', 0, '341,377', NULL, '1 if other heart and blood-vessel disease (angina, valve disease, irregular heartbeat, artery disease, mini-stroke, cardiac devices) was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_other_cvd, which looks back to January 2024.'),
  ('flag_dm_kidney_l12m', 'flag_dm_kidney_l12m', 'flag', 'Conditions and complications', 0, '341,377', NULL, '1 if diabetic kidney disease was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_dm_kidney, which looks back to January 2024.'),
  ('flag_dm_eye_l12m', 'flag_dm_eye_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M', '1 if a type 2 diabetes eye complication (E11.3x: retinopathy, macular oedema, cataract, other) was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_dm_eye, which looks back to January 2024.'),
  ('flag_dm_neuropathy_l12m', 'flag_dm_neuropathy_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M', '1 if diabetic nerve damage (E11.4x) was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_dm_neuropathy, which looks back to January 2024.'),
  ('flag_dm_circulatory_l12m', 'flag_dm_circulatory_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M', '1 if poor blood flow caused by diabetes (E11.5x) was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_dm_circulatory, which looks back to January 2024.'),
  ('flag_dm_foot_l12m', 'flag_dm_foot_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M; rule_trigger:Trig13', '1 if diabetic foot (foot ulcer, Charcot foot, peripheral artery disease with or without gangrene, foot bone infection) was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_dm_foot, which looks back to January 2024.'),
  ('flag_amputation_l12m', 'flag_amputation_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M; rule_trigger:Trig13', '1 if loss of a toe, foot or leg, or an amputation procedure was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_amputation, which looks back to January 2024.'),
  ('flag_dm_hypoglycaemia_l12m', 'flag_dm_hypoglycaemia_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_alert:RED; rule_risk_band:C; rule_safety_flag:safety; rule_trigger:Trig3', '1 if a low-blood-sugar episode (E11.64x or E16.0-E16.2) was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_dm_hypoglycaemia, which looks back to January 2024.'),
  ('flag_dm_hyperglycaemic_crisis_l12m', 'flag_dm_hyperglycaemic_crisis_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:C', '1 if dangerously high blood sugar (ketoacidosis or hyperosmolar state) was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_dm_hyperglycaemic_crisis, which looks back to January 2024.'),
  ('flag_sepsis_l12m', 'flag_sepsis_l12m', 'flag', 'Conditions and complications', 0, '341,377', NULL, '1 if sepsis was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_sepsis, which looks back to January 2024.'),
  ('flag_ischemic_heart_disease_l12m', 'flag_ischemic_heart_disease_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M', '1 if ischaemic heart disease (I20-I25) was billed in the last 12 months (Nov 2025 to Oct 2026). Same codes as flag_ischemic_heart_disease, which looks back to January 2024.'),
  ('flag_dyslipidemia_l12m', 'flag_dyslipidemia_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M', '1 if high cholesterol or another lipid disorder was billed in the last 12 months (Nov 2025 to Oct 2026) (E78, except E78.6 and E78.7).'),
  ('flag_obesity', 'flag_obesity', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M', '1 if the latest measured BMI is 30 or more (any date), or an obesity code was billed in the last 12 months (E66 except E66.3 overweight; Z68.3x / Z68.4x = BMI 30 or more).'),
  ('flag_cad_mi_l12m', 'flag_cad_mi_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M; rule_trigger:Trig2', '1 if coronary artery disease or heart attack was billed in the last 12 months (Nov 2025 to Oct 2026): I20-I25, or coronary bypass / stent / angioplasty status (Z95.1, Z95.5, Z98.61).'),
  ('flag_stroke_tia_l12m', 'flag_stroke_tia_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M', '1 if stroke or TIA was billed in the last 12 months (Nov 2025 to Oct 2026): I60-I64, I69, G46, G45 (except G45.4), or history of TIA / cerebral infarction (Z86.73).'),
  ('flag_pad_l12m', 'flag_pad_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M; rule_trigger:Trig13', '1 if peripheral arterial disease was billed in the last 12 months (Nov 2025 to Oct 2026): diabetic peripheral angiopathy (E11.51, E11.52), atherosclerosis of limb arteries or grafts (I70.2-I70.7), or peripheral vascular disease (I73.9).'),
  ('flag_dm_retinopathy_l12m', 'flag_dm_retinopathy_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M', '1 if diabetic retinopathy was billed in the last 12 months (Nov 2025 to Oct 2026) (E11.31-E11.35, with or without macular oedema; cataract and other eye codes not included).'),
  ('flag_peripheral_neuropathy_l12m', 'flag_peripheral_neuropathy_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M; rule_trigger:Trig13', '1 if peripheral neuropathy was billed in the last 12 months (Nov 2025 to Oct 2026): diabetic neuropathy unspecified / polyneuropathy (E11.40, E11.42), polyneuropathy (G62.9, G63).'),
  ('flag_dm_foot_ulcer_l12m', 'flag_dm_foot_ulcer_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M; rule_trigger:Trig13', '1 if a foot ulcer was billed in the last 12 months (Nov 2025 to Oct 2026): diabetic foot ulcer (E11.621) or a chronic ulcer of the heel, midfoot or other part of the foot (L97.4, L97.5).'),
  ('flag_major_amputation_l12m', 'flag_major_amputation_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_risk_band:M', '1 if a major (leg) amputation was billed in the last 12 months (Nov 2025 to Oct 2026): absence of leg below / above the knee (Z89.5, Z89.6), or below-knee, above-knee or hip amputation procedures. Toe, foot and ankle amputations are not included.'),
  ('flag_dka_l12m', 'flag_dka_l12m', 'flag', 'Conditions and complications', 1, '341,377', 'rule_alert:RED; rule_risk_band:C; rule_safety_flag:safety', '1 if diabetic ketoacidosis (E11.1x) was billed in the last 12 months (Nov 2025 to Oct 2026).'),
  ('Last_UACR_Value', 'last_uacr_value', 'num', 'Labs and readings', 1, '341,377', 'rule_builder_field_group:Tests & results; rule_risk_band:K; rule_trigger:Trig5', 'Latest urine albumin-to-creatinine ratio, mg/g (results in mg/mmol are converted: x 8.84). 30-299 = moderately raised, 300+ = severely raised.'),
